 tail=lambda pairs,alias='c':'('+' OR '.join('rx_matches('+alias+'.full_callee,'+q(r'(?:^|\.)'+re.escape(a)+r'(?:\([^)]*\))?\.'+re.escape(b)+r'$')+')' for a,b in sorted(pairs))+')' if pairs else '0'
 stages=python_stages()+[
 S('contexts',"WITH RECURSIVE class_parents(__path,id,name,parent) AS (SELECT n.__path,n.id,n.name_source,own.cls FROM nodes n LEFT JOIN ownership own ON own.__path=n.__path AND own.id=n.edge_parent WHERE n.kind='class_definition'), class_names(__path,id,name) AS (SELECT __path,id,name FROM class_parents WHERE parent IS NULL UNION ALL SELECT c.__path,c.id,p.name||'.'||c.name FROM class_names p JOIN class_parents c ON c.__path=p.__path AND c.parent=p.id) SELECT f.*,coalesce(qualified.name,'') AS class_name,rx_matches(f.name,'_lazy$') OR f.name IN "+literals(m.PURE_SCOPE_NAMES)+" OR f.name='pending_pipeline_effects' OR rx_matches(f.name,'^apply_.*_effect$') OR EXISTS(SELECT 1 FROM nodes w WHERE w.__path=f.__path AND w.id=f.parent AND w.kind='decorated_definition' AND rx_matches(w.text,'(?m)^\\s*@(?:[\\w.]*\\.)?pure_lazy\\b')) AS planning, f.name='preprocess' AS preprocess,substr(f.name,-11)='sql_builder' AND f.name NOT IN "+literals(m.PURE_SCOPE_NAMES)+" AND EXISTS(SELECT 1 FROM parameters p JOIN nodes ann ON ann.__path=p.__path AND ann.id=p.annotation WHERE p.__path=f.__path AND p.fn=f.id AND rx_matches(ann.text,'\\bCompilationContext\\b')) AS ctx_helper,f.__path="+q(m.BACKEND_PROVIDER_PURITY_FILE)+" AND rx_matches(f.name,"+q('|'.join(sorted(m.BACKEND_PROVIDER_PURITY_NAME_TOKENS)))+") AS provider_helper,EXISTS(SELECT 1 FROM parameters p WHERE p.__path=f.__path AND p.fn=f.id AND p.name='runtime_refs') AND (rx_matches(f.name,'^materialize_.*builder$') OR EXISTS(SELECT 1 FROM parameters p JOIN nodes ann ON ann.__path=p.__path AND ann.id=p.annotation WHERE p.__path=f.__path AND p.fn=f.id AND rx_matches(ann.text,'\\bRuntimeBuilderSpec\\b'))) AS materializer FROM functions f JOIN ownership own ON own.__path=f.__path AND own.id=f.id AND own.top_fn=f.id LEFT JOIN class_names qualified ON qualified.__path=f.__path AND qualified.id=own.cls",('__path','id'),('__path','name')),
 S('body_nodes',"SELECT own.__path,own.top_fn AS fn,own.id AS node FROM ownership own JOIN contexts c ON c.__path=own.__path AND c.id=own.top_fn",('__path','fn','node'),('__path','node','fn')),
 S('callback_parameters',"SELECT DISTINCT c.__path,c.id AS fn,p.name,k.name AS callback_kind,p.position FROM contexts c JOIN calls call ON call.__path=c.__path AND call.__start>=c.__start AND call.__end<=c.__end AND call.callee='CompiledStep' JOIN keywords k ON k.__path=call.__path AND k.call=call.id AND k.name IN ('post_op','post_op_with_refs') AND k.kind='identifier' JOIN functions nested ON nested.__path=c.__path AND nested.name=k.text AND nested.__start>c.__start AND nested.__end<=c.__end JOIN parameters p ON p.__path=nested.__path AND p.fn=nested.id WHERE p.position IN (1,2)",('__path','fn','name')),
 S('parameter_kinds',"SELECT p.__path,p.fn,p.name,'authority' AS kind FROM parameters p LEFT JOIN nodes ann ON ann.__path=p.__path AND ann.id=p.annotation WHERE p.name IN ('txn','read_txn','write_txn','conn','connection','sql_conn') OR rx_matches(coalesce(ann.text,''),"+q(r'\b(?:'+'|'.join(sorted(m.AUTHORITY_TYPE_NAMES))+r')\b')+") UNION SELECT p.__path,p.fn,p.name,'provider' FROM parameters p JOIN nodes ann ON ann.__path=p.__path AND ann.id=p.annotation WHERE rx_matches(ann.text,"+q(r'\b(?:'+'|'.join(sorted(m.PROVIDER_TYPE_NAMES))+r')\b')+") UNION SELECT p.__path,p.fn,p.name,'runtime_value' FROM parameters p LEFT JOIN nodes ann ON ann.__path=p.__path AND ann.id=p.annotation LEFT JOIN contexts c ON c.__path=p.__path AND c.id=p.fn WHERE p.name='resolved' OR rx_matches(coalesce(ann.text,''),'\\bResolvedRefs\\b') OR c.materializer AND p.name='runtime_refs' UNION SELECT p.__path,p.fn,p.name,'carrier' FROM parameters p LEFT JOIN nodes ann ON ann.__path=p.__path AND ann.id=p.annotation WHERE p.name IN ('hydrator','runtime_hydrator','runtime_refs') OR rx_matches(coalesce(ann.text,''),'\\bHydrator\\b') UNION SELECT __path,fn,name,CASE WHEN callback_kind='post_op_with_refs' AND position=2 THEN 'runtime_value' ELSE 'carrier' END FROM callback_parameters WHERE position=1 OR callback_kind='post_op_with_refs' AND position=2 UNION SELECT __path,fn,name,'carrier' FROM callback_parameters WHERE callback_kind='post_op_with_refs' AND position=2",('__path','fn','name','kind')),
 S('string_values',"SELECT __path,__start,__end,value FROM raw_strings UNION SELECT n.__path,n.__start,n.__end,s.value FROM assignments a JOIN nodes stmt ON stmt.__path=a.__path AND stmt.id=a.parent JOIN nodes root ON root.__path=stmt.__path AND root.id=stmt.parent AND root.kind='module' JOIN raw_strings s ON s.__path=a.__path AND s.__start=a.right_start AND s.__end=a.right_end JOIN nodes n ON n.__path=a.__path AND n.kind='identifier' AND n.text=a.target_text WHERE a.target_kind='identifier'",('__path','__start','__end')),
 S('special_attributes',"SELECT b.__path,b.fn,a.id AS node,CASE WHEN a.object_text='ctx' AND a.attr IN "+literals(m.COMPILATION_CONTEXT_AUTHORITY_ATTRS)+" THEN 'context' ELSE 'carrier' END AS owner,a.attr FROM attributes a JOIN body_nodes b ON b.__path=a.__path AND b.node=a.id WHERE a.object_text='ctx' AND a.attr IN "+literals(m.COMPILATION_CONTEXT_AUTHORITY_ATTRS)+" OR a.attr IN "+literals(m.RUNTIME_CALLBACK_AUTHORITY_ATTRS)+" AND EXISTS(SELECT 1 FROM parameter_kinds p WHERE p.__path=b.__path AND p.fn=b.fn AND p.name=a.object_text AND p.kind='carrier') UNION SELECT b.__path,b.fn,c.id,CASE WHEN receiver.text='ctx' AND c.full_callee='getattr' THEN 'context' ELSE 'carrier' END,s.value FROM calls c JOIN body_nodes b ON b.__path=c.__path AND b.node=c.id JOIN arguments receiver ON receiver.__path=c.__path AND receiver.call=c.id AND receiver.position=0 JOIN arguments key ON key.__path=c.__path AND key.call=c.id AND key.position=1 JOIN string_values s ON s.__path=key.__path AND s.__start=key.__start AND s.__end=key.__end WHERE c.full_callee='getattr' AND receiver.kind='identifier' AND (receiver.text='ctx' AND s.value IN "+literals(m.COMPILATION_CONTEXT_AUTHORITY_ATTRS)+" OR s.value IN "+literals(m.RUNTIME_CALLBACK_AUTHORITY_ATTRS)+" AND EXISTS(SELECT 1 FROM parameter_kinds p WHERE p.__path=b.__path AND p.fn=b.fn AND p.name=receiver.text AND p.kind='carrier')) UNION SELECT b.__path,b.fn,c.id,'carrier',s.value FROM calls c JOIN body_nodes b ON b.__path=c.__path AND b.node=c.id JOIN attributes a ON a.__path=c.__path AND a.id=c.callee_id JOIN arguments key ON key.__path=c.__path AND key.call=c.id AND key.position=0 JOIN string_values s ON s.__path=key.__path AND s.__start=key.__start AND s.__end=key.__end WHERE c.callee='get' AND s.value IN "+literals(m.RUNTIME_CALLBACK_AUTHORITY_ATTRS)+" AND EXISTS(SELECT 1 FROM parameter_kinds p WHERE p.__path=b.__path AND p.fn=b.fn AND p.name=a.object_text AND p.kind='carrier') UNION SELECT b.__path,b.fn,n.id,'carrier',s.value FROM nodes n JOIN body_nodes b ON b.__path=n.__path AND b.node=n.id JOIN nodes receiver ON receiver.__path=n.__path AND receiver.id=n.value_kind||':'||n.value_start||':'||n.value_end JOIN nodes key ON key.__path=n.__path AND key.parent=n.id AND key.id!=receiver.id JOIN string_values s ON s.__path=key.__path AND s.__start=key.__start AND s.__end=key.__end WHERE n.kind='subscript' AND receiver.kind='identifier' AND s.value IN "+literals(m.RUNTIME_CALLBACK_AUTHORITY_ATTRS)+" AND EXISTS(SELECT 1 FROM parameter_kinds p WHERE p.__path=b.__path AND p.fn=b.fn AND p.name=receiver.text AND p.kind='carrier')",('__path','fn','node')),
 S('return_kinds',"WITH RECURSIVE runtime(__path,name) AS (SELECT DISTINCT c.__path,c.name FROM contexts c JOIN special_attributes a ON a.__path=c.__path AND a.fn=c.id AND a.owner='carrier' WHERE EXISTS(SELECT 1 FROM parameter_kinds p WHERE p.__path=c.__path AND p.fn=c.id AND p.kind='carrier') UNION SELECT DISTINCT c.__path,c.name FROM contexts c JOIN body_nodes b ON b.__path=c.__path AND b.fn=c.id JOIN calls call ON call.__path=b.__path AND call.id=b.node AND call.callee_kind='identifier' JOIN runtime r ON r.__path=call.__path AND r.name=call.callee WHERE EXISTS(SELECT 1 FROM arguments arg JOIN descendants d ON d.__path=arg.__path AND d.root=arg.id JOIN nodes n ON n.__path=d.__path AND n.id=d.node AND n.kind='identifier' JOIN parameter_kinds p ON p.__path=c.__path AND p.fn=c.id AND p.name=n.text AND p.kind='carrier' WHERE arg.__path=call.__path AND arg.call=call.id)) SELECT __path,name,'runtime_authority' AS kind FROM runtime UNION SELECT c.__path,c.name,'authority' FROM contexts c JOIN nodes ann ON ann.__path=c.__path AND ann.id=c.return_type_kind||':'||c.return_type_start||':'||c.return_type_end WHERE rx_matches(ann.text,"+q(r'\b(?:'+'|'.join(sorted(m.AUTHORITY_TYPE_NAMES))+r')\b')+") UNION SELECT c.__path,c.name,'provider' FROM contexts c JOIN nodes ann ON ann.__path=c.__path AND ann.id=c.return_type_kind||':'||c.return_type_start||':'||c.return_type_end WHERE rx_matches(ann.text,"+q(r'\b(?:'+'|'.join(sorted(m.PROVIDER_TYPE_NAMES))+r')\b')+")",('__path','name','kind')),
 S('expression_edges',"SELECT __path,id AS dst,object AS src FROM attributes UNION SELECT __path,id,receiver FROM calls WHERE receiver IS NOT NULL UNION SELECT __path,id,value_kind||':'||value_start||':'||value_end FROM nodes WHERE kind='subscript'",('__path','src','dst')),
 S('identifier_nodes',"SELECT __path,id,text,kind FROM nodes WHERE kind='identifier'",('__path','text'),('__path','id')),
 S('taints',"WITH RECURSIVE taint(__path,fn,node,kind) AS (SELECT b.__path,b.fn,n.id,p.kind FROM body_nodes b JOIN identifier_nodes n ON n.__path=b.__path AND n.id=b.node AND n.kind='identifier' JOIN parameter_kinds p ON p.__path=b.__path AND p.fn=b.fn AND p.name=n.text WHERE p.kind!='carrier' UNION SELECT __path,fn,node,'authority' FROM special_attributes WHERE owner='carrier' OR attr IN ('txn','sql_connection') UNION SELECT b.__path,b.fn,c.id,r.kind FROM body_nodes b JOIN calls c ON c.__path=b.__path AND c.id=b.node JOIN return_kinds r ON (r.__path=c.__path OR EXISTS(SELECT 1 FROM project_mode)) AND r.name=c.callee UNION SELECT t.__path,t.fn,e.dst,t.kind FROM taint t JOIN expression_edges e ON e.__path=t.__path AND e.src=t.node JOIN body_nodes b ON b.__path=t.__path AND b.fn=t.fn AND b.node=e.dst UNION SELECT t.__path,t.fn,n.id,t.kind FROM taint t JOIN assignments a ON a.__path=t.__path AND a.value=t.node JOIN body_nodes b ON b.__path=a.__path AND b.fn=t.fn AND b.node=a.id JOIN identifier_nodes n ON n.__path=b.__path AND n.kind='identifier' AND n.text=a.target_text JOIN body_nodes uses ON uses.__path=n.__path AND uses.fn=t.fn AND uses.node=n.id WHERE a.target_kind='identifier' AND t.kind IN ('authority','provider','runtime_value')) SELECT * FROM taint",('__path','fn','node','kind')),
 S('semantic_values',"WITH RECURSIVE semantic(__path,fn,node) AS (SELECT __path,fn,node FROM taints WHERE kind='runtime_value' UNION SELECT b.__path,b.fn,n.id FROM body_nodes b JOIN identifier_nodes n ON n.__path=b.__path AND n.id=b.node AND n.kind='identifier' JOIN parameter_kinds p ON p.__path=b.__path AND p.fn=b.fn AND p.name=n.text AND p.kind='carrier' UNION SELECT s.__path,s.fn,d.root FROM semantic s JOIN descendants d ON d.__path=s.__path AND d.node=s.node UNION SELECT s.__path,s.fn,n.id FROM semantic s JOIN assignments a ON a.__path=s.__path AND a.value=s.node JOIN body_nodes b ON b.__path=a.__path AND b.fn=s.fn AND b.node=a.id JOIN identifier_nodes n ON n.__path=s.__path AND n.kind='identifier' AND n.text=a.target_text JOIN body_nodes uses ON uses.__path=n.__path AND uses.fn=s.fn AND uses.node=n.id WHERE a.target_kind='identifier') SELECT * FROM semantic",('__path','fn','node')),
 ]
