 sinks=[]
 def sink(kind,table,where,join='',priority='1'):
  sinks.append(f"SELECT b.__path,b.fn,n.id AS node,{q(kind)} AS kind,{priority} AS priority FROM {table} n JOIN body_nodes b ON b.__path=n.__path AND b.node=n.id {join} WHERE {where}")
 sink('eager_sql','calls',"n.callee IN "+literals(m.DIRECT_IO_NAMES)+" OR n.callee_kind='identifier' AND n.callee IN "+literals(m.PREPROCESS_SQL_EXECUTION_NAMES)+" OR "+tail(m.FORBIDDEN_QUERY_CALL_TAILS|m.PREPROCESS_SQL_EXECUTION_CALL_TAILS,'n')+" OR n.callee IN "+literals(m.PREPROCESS_SQL_EXECUTION_NAMES)+" AND EXISTS(SELECT 1 FROM taints t WHERE t.__path=b.__path AND t.fn=b.fn AND t.node=n.receiver AND t.kind='authority')")
 sink('native_python_work','calls',"n.callee IN "+literals(m.FORBIDDEN_NATIVE_PYTHON_CALL_NAMES)+" OR "+tail(m.FORBIDDEN_NATIVE_PYTHON_CALL_CHAINS,'n'))
 sink('runtime_callback','calls',"n.callee='CompiledStep' AND EXISTS(SELECT 1 FROM keywords k WHERE k.__path=n.__path AND k.call=n.id AND k.name IN ('post_op_with_refs','pre_op_with_refs'))")
